// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/scenes/VidaiScene.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { Cloud, PalaceSkyline, SunOnWire } from "../sets/Sky";
import { GATE, GateGlow, PalaceGate } from "../sets/WeddingDayGate";
import { people, wardrobe } from "../characters/cast";
import type { Outfit, Person, Pose } from "../characters/types";
import { Figure, Gate, SVG, colorAt, fig, reach, reachPose, toScene, type Fig, type Pt } from "../props/WeddingDayKit";
import { Lantern } from "../props/WeddingDayDecor";
import { Varmala } from "../props/WeddingDayGarland";
import { Stars } from "../props/WeddingDayProps";
import { Diya } from "../props/Ganesh";
import { MarigoldStrand } from "../props/Florals";
import { Silhouette } from "../kit/Idle";
import { FallingPetals } from "../kit/Particles";
import { EventTitle } from "../kit/EventTitle";
import { EASE, prog, wave } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

const BASE = GATE.base;
const MID = GATE.arch.x + GATE.arch.w / 2;
const R = fig(people.rishabh, MID - 62, BASE, 600);
const N = fig(people.nandita, MID + 62, BASE, 600);

type Farewell = { p: Person; o: Outfit; f: Fig; side: "l" | "r"; delay: number };
const family: Farewell[] = [
  { p: people.rewa, o: wardrobe.rewa.wedding, f: fig(people.rewa, 80, 2080, 720), side: "r", delay: 26 },
  { p: people.vinod, o: wardrobe.vinod.catalogue, f: fig(people.vinod, 215, 2150, 780), side: "r", delay: 40 },
  { p: people.hardik, o: wardrobe.hardik.catalogue, f: fig(people.hardik, 880, 2140, 770), side: "l", delay: 34 },
  { p: people.guestF2, o: wardrobe.guestF2.festive, f: fig(people.guestF2, 1010, 2070, 720), side: "l", delay: 48 },
];

/**
 * Vidai — dusk at the palace gate. The couple stands in the lantern-lit arch, Nandita's hand
 * raised in farewell; family hands rise in silhouette; petals and rice drift in slow motion while
 * the camera cranes up to the first stars and the sun sinks on its wire.
 */
export const VidaiScene: React.FC<SceneProps> = ({ inv, dur }) => {
  const frame = useCurrentFrame();
  const dusk = prog(frame, 0, dur - 60, EASE.inOut);
  const cam = useCamera([
    { frame: 0, y: 170, scale: 1.02 },
    { frame: dur - 10, y: 0, scale: 1.0, ease: EASE.cine },
  ]);

  const top = colorAt(dusk, ["#5A3A62", "#3B2A4E"]);
  const mid = colorAt(dusk, ["#B0607A", "#8A4A6C"]);
  const low = colorAt(dusk, ["#F0A06A", "#E27E56"]);
  const sunT = 0.9 + prog(frame, 0, dur - 30, EASE.inOut) * 0.08;
  const sunDrop = 80 + prog(frame, 0, dur - 30, EASE.inOut) * 360;

  // the couple: hand in hand; her free hand rises softly in farewell
  const clasp: Pt = [MID, toScene(R, 200, 590)[1]];
  const raise = prog(frame, 30, 44, EASE.inOut);
  const farewellHand: Pt = [toScene(N, 330, 260)[0] + raise * 20, toScene(N, 330, 260)[1] - raise * 150 + Math.sin((frame - 30) / 26) * 6 * raise];
  const nPose: Partial<Pose> = {
    ...reachPose(N, clasp, null, -1, 1),
    ...(() => {
      const r = reach(N, "r", farewellHand, -1);
      return { rShoulder: r.shoulder * raise + -7 * (1 - raise), rElbow: r.elbow * raise + 6 * (1 - raise) };
    })(),
    headTilt: -3 + wave(frame, 160) * 0.6,
  };
  const rPose: Partial<Pose> = { ...reachPose(R, null, clasp, -1, 1), lShoulder: 8, lElbow: -8, headTilt: 3 + wave(frame, 170, 1) * 0.6 };

  const item = inv.events.weddingDay.items.find((i) => i.id === "vidai");
  const titleStart = Math.min(92, dur - 110 - 52);

  return (
    <Stage background="#3B2A4E">
      <Camera state={cam}>
        {/* SKY — violet to ember; first stars appear as we rise */}
        <ParallaxLayer depth={0.1} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="vidai-sky" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor={top} />
                <stop offset="0.45" stopColor={mid} />
                <stop offset="0.62" stopColor={low} />
                <stop offset="1" stopColor={low} />
              </linearGradient>
            </defs>
            <rect x={-100} y={-500} width={1280} height={2500} fill="url(#vidai-sky)" />
          </SVG>
          <PaperBackground stock="cream" seed="vidai-sky" fibres={16} textureOnly />
        </ParallaxLayer>
        <ParallaxLayer depth={0.14} blurStrength={0}>
          <SVG>
            <Stars frame={frame} show={prog(frame, 20, 130, EASE.inOut)} area={[70, -220, 940, 760]} count={40} seed="vidai-stars" color={palette.goldPale} />
            <Cloud x={620} y={560} w={260} fill={colorAt(dusk, ["#C87482", "#9A5872"])} line={palette.goldLight} />
            <Cloud x={-40} y={760} w={220} fill={colorAt(dusk, ["#D08A82", "#A8607A"])} />
          </SVG>
        </ParallaxLayer>
        <ParallaxLayer depth={0.2} blurStrength={0}>
          <SVG>
            <SunOnWire t={sunT} drop={sunDrop} />
          </SVG>
        </ParallaxLayer>

        {/* FAR — the city at dusk */}
        <ParallaxLayer depth={0.35} blurStrength={0}>
          <SVG>
            <PalaceSkyline fill="#6E3E5A" y={1010} accent="#F2B070" />
            <rect x={-100} y={1270} width={1300} height={800} fill="#5A3450" />
          </SVG>
        </ParallaxLayer>

        {/* GATE — glowing arch, couple within, lanterns */}
        <ParallaxLayer depth={1} blurStrength={0}>
          <SVG>
            <GateGlow id="vidai-glow" intensity={0.9 + wave(frame, 60) * 0.05} />
            <rect x={-100} y={BASE + 30} width={1300} height={700} fill="#3E2638" />
            {[1560, 1640, 1760].map((y) => (
              <rect key={y} x={-100} y={y} width={1300} height={1} fill={palette.goldLight} opacity={0.14} />
            ))}
          </SVG>
          <Figure f={R} person={people.rishabh} outfit={wardrobe.rishabh.wedding} pose={rPose} />
          <Figure f={N} person={people.nandita} outfit={wardrobe.nandita.wedding} pose={nPose} />
          <SVG>
            <Varmala a={toScene(R, 146, 250)} b={toScene(R, 254, 250)} sag={190} r={9} seed="vd-r" />
            <Varmala a={toScene(N, 150, 250)} b={toScene(N, 250, 250)} sag={176} r={9} seed="vd-n" tones={["ivory", "rose", "orange", "ivory", "rose", "yellow"]} />
            <PalaceGate wall="#9A6468" shade="#6E4252" trim="#E2B774" lit="#FFD58E" />
            {[GATE.arch.x + 22, GATE.arch.x + GATE.arch.w - 22].map((x, i) => (
              <MarigoldStrand key={x} x={x} y={GATE.arch.spring - 150} length={260} r={10} seed={`vd-ms${i}`} sway={wave(frame, 140, i) * 4} />
            ))}
            {[GATE.x0 - 40, GATE.x1 + 40].map((x, i) => (
              <Lantern key={`o${x}`} x={x} y={880} len={50} s={0.95} swing={wave(frame, 120, i + 1) * 2} id={`vidai-lo${i}`} />
            ))}
          </SVG>
          {[GATE.arch.x - 70, GATE.arch.x - 10, GATE.arch.x + GATE.arch.w - 50, GATE.arch.x + GATE.arch.w + 10].map((x, i) => (
            <div key={x} style={{ position: "absolute", left: x, top: BASE - 34 + (i % 2 ? 16 : 0) }}>
              <Diya size={64} flicker={frame / 7 + i} />
            </div>
          ))}
        </ParallaxLayer>

        {/* SLOW PETALS & RICE */}
        <FallingPetals count={18} seed="vidai-petals" speed={0.32} start={-300} size={1.1} colors={[palette.rose, palette.roseLight, palette.marigold]} opacity={0.9} />
        <FallingPetals count={30} seed="vidai-rice" speed={0.4} start={-300} size={0.32} colors={["#FFF8E6", "#F6EBD2"]} />

        {/* FOREGROUND — family hands raised, in silhouette */}
        <ParallaxLayer depth={1.3} blurStrength={0}>
          {family.map((m, i) => {
            const up = prog(frame, m.delay, 40, EASE.inOut);
            const sway = Math.sin((frame - m.delay) / 30 + i) * 4 * up;
            const pose: Partial<Pose> =
              m.side === "r"
                ? { rShoulder: -7 - up * 150 + sway, rElbow: 6 - up * 38, lShoulder: 8, lElbow: -10, headTilt: 4 }
                : { lShoulder: 7 + up * 150 + sway, lElbow: -6 + up * 38, rShoulder: -8, rElbow: 10, headTilt: -4 };
            return (
              <Silhouette key={i} opacity={0.8} style={{ position: "absolute", inset: 0 }}>
                <Figure f={m.f} person={m.p} outfit={m.o} pose={pose} />
              </Silhouette>
            );
          })}
        </ParallaxLayer>
      </Camera>

      <SceneLighting
        warmth={0.3}
        keyX={90}
        keyY={40}
        spots={[
          { x: MID / 10.8, y: 64, r: 34, color: "#FFC27A", intensity: 0.3 },
          { x: 92, y: 45, r: 30, color: "#FF9E62", intensity: 0.22 * (1 - dusk * 0.5) },
        ]}
        vignette={0.5}
      />

      <AbsoluteFill>
        <Gate from={titleStart}>
          <EventTitle start={titleStart} kicker="With Love & Blessings" title={item?.title ?? "Vidai"} lines={[whenBi(inv.events.weddingDay.date, item?.time), bi(inv.events.weddingDay.venue)]} top={1606} titleSize={100} theme="light" />
        </Gate>
      </AbsoluteFill>

      <GoldFrame />
    </Stage>
  );
};
